"""Private pytest subprocess protocol: preserve actual node IDs and phase outcomes."""
import json
import os
from pathlib import Path

_collected = []
_results = {}


def pytest_collection_finish(session):
    _collected.extend({"id": item.nodeid, "file": str(item.path), "name": item.name} for item in session.items)


def pytest_runtest_logreport(report):
    row = _results.setdefault(report.nodeid, {"id": report.nodeid, "status": "passed", "duration": 0.0})
    row["duration"] += report.duration * 1000
    if report.failed:
        row["status"] = "failed"
        row["error"] = {"message": f"{report.when} failed", "stack": str(report.longrepr)}
    elif report.skipped and row["status"] != "failed":
        row["status"] = "skipped"


def pytest_sessionfinish(session, exitstatus):
    Path(os.environ["TESTFN_REPORT"]).write_text(json.dumps({
        "collected": _collected, "results": list(_results.values()), "exitstatus": int(exitstatus),
    }), encoding="utf-8")
